import type { LocaleTree } from '../i18n/types'

/**
 * Gekeyed op quote-id. Bevat 300 unieke, handgeschreven Risk quotes,
 * elk met een `text`- en `author`-veld (nl/en). Auteurs zijn ofwel
 * overgenomen uit de oorspronkelijke quote (herkenbaar aan het
 * gedachtestreepje) of kort verzonnen wanneer de quote er geen had.
 */
export const quotes = {
 'quote-1': { text: { nl: 'Vriendschap is een illusie die eindigt bij de grens van Kamtsjatka.', en: 'Friendship is an illusion that ends at the border of Kamchatka.' }, author: { nl: 'Oude veldheerswijsheid', en: 'Old commander\'s wisdom' } },
 'quote-2': { text: { nl: 'Niemand heeft ooit de wereld veroverd door zich te verstoppen in West-Australië.', en: 'No one ever conquered the world by hiding in Western Australia.' }, author: { nl: 'Overwinnaar van gisteren', en: 'Yesterday\'s victor' } },
 'quote-3': { text: { nl: 'Een vredesverdrag in Risk is slechts een pauze om troepen te verzamelen.', en: 'A peace treaty in Risk is merely a pause to gather troops.' }, author: { nl: 'Kamergeleerde in tactiek', en: 'Armchair tactics scholar' } },
 'quote-4': { text: { nl: 'Drie artilleriekaarten inleveren is het equivalent van een goddelijke interventie.', en: 'Turning in three artillery cards is the equivalent of divine intervention.' }, author: { nl: 'Generaal aan het front', en: 'General at the front' } },
 'quote-5': { text: { nl: 'De echte vijand is niet je tegenstander, maar de rode dobbelsteen.', en: 'The real enemy is not your opponent, but the red die.' }, author: { nl: 'Anonieme militair strateeg', en: 'Anonymous military strategist' } },
 'quote-6': { text: { nl: 'Azië verdedigen is een fulltime baan zonder pensioen.', en: 'Defending Asia is a full-time job with no retirement plan.' }, author: { nl: 'Een stille waarnemer', en: 'A quiet observer' } },
 'quote-7': { text: { nl: 'Zuid-Amerika is een fort, totdat Noord-Afrika langskomt.', en: 'South America is a fortress, until North Africa drops by.' }, author: { nl: 'Strategisch handboek', en: 'Strategy handbook' } },
 'quote-8': { text: { nl: 'Je kan een man beoordelen op hoe hij reageert op een aanval vanuit IJsland.', en: 'You can judge a man by how he reacts to an attack from Iceland.' }, author: { nl: 'Een oud-bondgenoot', en: 'A former ally' } },
 'quote-9': { text: { nl: 'Er is geen grotere pijn dan veertig legers verliezen aan één boze boer in Oeral.', en: 'There is no greater pain than losing forty armies to one angry farmer in Ural.' }, author: { nl: 'De verliezende coalitie', en: 'The losing coalition' } },
 'quote-10': { text: { nl: 'De Joker-kaart trekt geen vooroordelen; hij vernietigt ze.', en: 'The Joker card holds no prejudices; it destroys them.' }, author: { nl: 'Een anonieme diplomaat', en: 'An anonymous diplomat' } },
 'quote-11': { text: { nl: 'Een niet-aanvalsverdrag is het eerste slachtoffer van beurt drie.', en: 'A non-aggression pact is the first casualty of turn three.' }, author: { nl: 'Een verraden bondgenoot', en: 'A betrayed ally' } },
 'quote-12': { text: { nl: 'Wie Europa bezit, trekt vijanden aan als een magneet.', en: 'Whoever holds Europe attracts enemies like a magnet.' }, author: { nl: 'Een zelfingenomen kolonel', en: 'A self-satisfied colonel' } },
 'quote-13': { text: { nl: 'De grens tussen genialiteit en waanzin ligt ergens bij Groenland.', en: 'The line between genius and madness lies somewhere near Greenland.' }, author: { nl: 'De kaartenkamer', en: 'The map room' } },
 'quote-14': { text: { nl: 'Verdeel en heers, tenzij je gewoon slechte dobbelstenen hebt.', en: 'Divide and conquer, unless you just have terrible dice.' }, author: { nl: 'Het dobbelsteenorakel', en: 'The dice oracle' } },
 'quote-15': { text: { nl: 'Een grensconflict in het Midden-Oosten eindigt altijd op het bord.', en: 'A border conflict in the Middle East always ends on the board.' }, author: { nl: 'Ongevraagd advies van een buurland', en: 'Unsolicited advice from a neighbor' } },
 'quote-16': { text: { nl: 'Hoop is geen strategie, maar drie zessen gooien wel.', en: 'Hope is not a strategy, but rolling three sixes is.' }, author: { nl: 'Een ambitieuze admiraal', en: 'An ambitious admiral' } },
 'quote-17': { text: { nl: 'Het bord omdraaien telt niet als een legitieme tactische terugtrekking.', en: 'Flipping the board does not count as a legitimate tactical retreat.' }, author: { nl: 'Voetnoot in het spelregelboekje', en: 'Footnote in the rulebook' } },
 'quote-18': { text: { nl: 'In de oorlog en in Risk is alles geoorloofd.', en: 'All is fair in love, war, and Risk.' }, author: { nl: 'Een speler met te veel legers', en: 'A player with too many armies' } },
 'quote-19': { text: { nl: 'De val van Afrika begint altijd met een \'kleine grenscontrole\'.', en: 'The fall of Africa always begins with a \'minor border check\'.' }, author: { nl: 'Veldheer in ruste', en: 'Retired commander' } },
 'quote-20': { text: { nl: 'Zeven continenten, maar er is slechts ruimte voor één ego.', en: 'Seven continents, but only room for one ego.' }, author: { nl: 'Veroveraar in spe', en: 'Conqueror in the making' } },
 'quote-21': { text: { nl: 'Een ware veldheer klaagt nooit over de worp van de verdediger.', en: 'A true commander never complains about the defender\'s roll.' }, author: { nl: 'Een speler met te weinig geluk', en: 'A player with too little luck' } },
 'quote-22': { text: { nl: 'Het aanhouden van Noord-Amerika vereist paranoia en veel plastic.', en: 'Holding North America requires paranoia and a lot of plastic.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-23': { text: { nl: 'De definitie van waanzin is Kamtsjatka aanvallen in de winter.', en: 'The definition of insanity is attacking Kamchatka in the winter.' }, author: { nl: 'Gepensioneerd veldmaarschalk', en: 'Retired field marshal' } },
 'quote-24': { text: { nl: 'Een belofte om niet aan te vallen is slechts een toekomstige oorlogsverklaring.', en: 'A promise not to attack is just a future declaration of war.' }, author: { nl: 'De stem van de rode dobbelsteen', en: 'The voice of the red die' } },
 'quote-25': { text: { nl: 'Overmoed is de snelste route naar uitschakeling.', en: 'Overconfidence is the fastest route to elimination.' }, author: { nl: 'Cynische kolonel', en: 'Cynical colonel' } },
 'quote-26': { text: { nl: 'Je mag één speler vertrouwen, totdat hij de kaarten inlevert.', en: 'You may trust one player, until they turn in their cards.' }, author: { nl: 'Waarnemer aan de zijlijn', en: 'Sideline observer' } },
 'quote-27': { text: { nl: 'Het Midden-Oosten is geen territorium, het is een doorgeefluik.', en: 'The Middle East is not a territory, it is a transit lounge.' }, author: { nl: 'Een moedeloze aanvaller', en: 'A disheartened attacker' } },
 'quote-28': { text: { nl: 'Elke meesterzet overleeft de eerste dobbelsteenworp niet.', en: 'No masterstroke survives the first roll of the dice.' }, author: { nl: 'Onbekende strateeg', en: 'Unknown strategist' } },
 'quote-29': { text: { nl: 'Kijk uit voor de stille speler in Zuid-Afrika.', en: 'Beware the quiet player in South Africa.' }, author: { nl: 'Toeschouwer met een mening', en: 'Opinionated onlooker' } },
 'quote-30': { text: { nl: 'Het verzamelen van infanterie is de hobby van de verliezer.', en: 'Collecting infantry is the hobby of the loser.' }, author: { nl: 'Een hoopvolle verdediger', en: 'A hopeful defender' } },
 'quote-31': { text: { nl: 'Zonder cavalerie ben je nergens.', en: 'Without cavalry, you are going nowhere.' }, author: { nl: 'Napoleon, waarschijnlijk', en: 'Napoleon, probably' } },
 'quote-32': { text: { nl: 'Het bezitten van Madagaskar geeft een vals gevoel van veiligheid.', en: 'Owning Madagascar provides a false sense of security.' }, author: { nl: 'Doorgewinterde veteraan', en: 'Seasoned veteran' } },
 'quote-33': { text: { nl: 'Een massale opmars stopt altijd bij een bescheiden verdedigingslinie in Siberië.', en: 'A massive advance always halts at a modest defensive line in Siberia.' }, author: { nl: 'Een kaartenhamsteraar', en: 'A card hoarder' } },
 'quote-34': { text: { nl: 'Niets test familiebanden zoals het binnenvallen van Ontario.', en: 'Nothing tests family bonds quite like invading Ontario.' }, author: { nl: 'Kroniekschrijver van het bord', en: 'Chronicler of the board' } },
 'quote-35': { text: { nl: 'De grootste fout is de oorlog op twee fronten beginnen, de tweede is Australië negeren.', en: 'The biggest mistake is starting a two-front war, the second is ignoring Australia.' }, author: { nl: 'Bordspelfilosoof', en: 'Board game philosopher' } },
 'quote-36': { text: { nl: 'Alleen de doden hebben het einde van het spel gezien.', en: 'Only the dead have seen the end of the game.' }, author: { nl: 'Legendarische verliezer', en: 'Legendary loser' } },
 'quote-37': { text: { nl: 'Zes legers in Japan zijn volkomen nutteloos als de oorlog in Brazilië is.', en: 'Six armies in Japan are completely useless when the war is in Brazil.' }, author: { nl: 'Een speler zonder bondgenoten', en: 'A player without allies' } },
 'quote-38': { text: { nl: 'Het is makkelijker om een continent te veroveren dan de kleur zwart te bemachtigen.', en: 'It is easier to conquer a continent than to secure the black pieces.' }, author: { nl: 'De legerleiding', en: 'Army command' } },
 'quote-39': { text: { nl: 'De artillerie verplaatst zich traag, maar de wraak is onverbiddelijk.', en: 'The artillery moves slowly, but vengeance is inexorable.' }, author: { nl: 'Een zenuwachtige bondgenoot', en: 'A nervous ally' } },
 'quote-40': { text: { nl: 'Elke overwinning is te danken aan strategie, elke nederlaag aan de dobbelstenen.', en: 'Every victory is credited to strategy, every defeat to the dice.' }, author: { nl: 'De laatste kaartenstapel', en: 'The last deck of cards' } },
 'quote-41': { text: { nl: 'Een bondgenootschap met je buurman is als slapen met een oog open.', en: 'An alliance with your neighbor is like sleeping with one eye open.' }, author: { nl: 'Frontlinie-wijsheid', en: 'Frontline wisdom' } },
 'quote-42': { text: { nl: 'Een eenzame strijder in Afghanistan heeft al meer legers vernietigd dan de winter.', en: 'A lone warrior in Afghanistan has destroyed more armies than the winter.' }, author: { nl: 'Onderhandelaar zonder resultaat', en: 'Negotiator with no results' } },
 'quote-43': { text: { nl: 'Wrok is de krachtigste brandstof voor je legers.', en: 'Grudges are the most potent fuel for your armies.' }, author: { nl: 'Een tacticus uit het niets', en: 'A tactician out of nowhere' } },
 'quote-44': { text: { nl: 'Er is geen genade in het inleveren van kaarten op het juiste moment.', en: 'There is no mercy in turning in cards at the exact right moment.' }, author: { nl: 'Een verbitterde verliezer', en: 'A bitter loser' } },
 'quote-45': { text: { nl: 'Een overvalstactiek in Oost-Australië is het absolute dieptepunt van militaire eer.', en: 'An ambush tactic in Eastern Australia is the absolute rock bottom of military honor.' }, author: { nl: 'Een tevreden veroveraar', en: 'A satisfied conqueror' } },
 'quote-46': { text: { nl: 'Je hoeft niet de hele wereld te controleren, zolang je vijand maar niets heeft.', en: 'You don\'t need to control the whole world, as long as your enemy has nothing.' }, author: { nl: 'Wijze woorden bij het opruimen van het bord', en: 'Wise words while packing up the board' } },
 'quote-47': { text: { nl: 'Een zwakke grens trekt ongewenste toeristen aan, gewapend met dobbelstenen.', en: 'A weak border attracts unwanted tourists, armed with dice.' }, author: { nl: 'Zelfverklaarde keizer', en: 'Self-proclaimed emperor' } },
 'quote-48': { text: { nl: 'De weg naar de hel is geplaveid met legers die net één gebied tekort kwamen.', en: 'The road to hell is paved with armies that fell one territory short.' }, author: { nl: 'Laatste overlevende speler', en: 'Last surviving player' } },
 'quote-49': { text: { nl: 'Zeggen \'dit is gewoon een spelletje\' telt als een oorlogsverklaring.', en: 'Saying \'this is just a game\' counts as a declaration of war.' }, author: { nl: 'Een generaal zonder leger', en: 'A general without an army' } },
 'quote-50': { text: { nl: 'Geduld is een schone zaak, maar artillerie is beter.', en: 'Patience is a virtue, but artillery is better.' }, author: { nl: 'Een achterbankgeneraal', en: 'An armchair general' } },
 'quote-51': { text: { nl: 'Europa is een wespennest met grenzen getrokken door gekken.', en: 'Europe is a hornet\'s nest with borders drawn by madmen.' }, author: { nl: 'Een gefrustreerde uitdager', en: 'A frustrated challenger' } },
 'quote-52': { text: { nl: 'Het innemen van de laatste regio vereist offers die je vrienden nooit zullen vergeven.', en: 'Taking the final region requires sacrifices your friends will never forgive.' }, author: { nl: 'Oude veldheerswijsheid', en: 'Old commander\'s wisdom' } },
 'quote-53': { text: { nl: 'Een sterke verdediging in de Oekraïne breekt de rug van elk westers leger.', en: 'A strong defense in Ukraine breaks the back of any western army.' }, author: { nl: 'Overwinnaar van gisteren', en: 'Yesterday\'s victor' } },
 'quote-54': { text: { nl: 'Je kan geen continent bouwen op gebroken beloften.', en: 'You cannot build a continent on broken promises.' }, author: { nl: 'Kamergeleerde in tactiek', en: 'Armchair tactics scholar' } },
 'quote-55': { text: { nl: 'De meest gevaarlijke man is degene met niets te verliezen en één infanterie-eenheid in Congo.', en: 'The most dangerous man is the one with nothing to lose and one infantry unit in Congo.' }, author: { nl: 'Generaal aan het front', en: 'General at the front' } },
 'quote-56': { text: { nl: 'Twee enen werpen op het moment suprême is een karakterbouwende ervaring.', en: 'Rolling two ones at the critical moment is a character-building experience.' }, author: { nl: 'Anonieme militair strateeg', en: 'Anonymous military strategist' } },
 'quote-57': { text: { nl: 'Als de joker opduikt, verdwijnt alle diplomatie.', en: 'When the joker appears, all diplomacy vanishes.' }, author: { nl: 'Een stille waarnemer', en: 'A quiet observer' } },
 'quote-58': { text: { nl: 'De wereld behoort toe aan de speler die de meeste kaarten heeft gespaard.', en: 'The world belongs to the player who has hoarded the most cards.' }, author: { nl: 'Strategisch handboek', en: 'Strategy handbook' } },
 'quote-59': { text: { nl: 'Niemand is onschuldig in Oosterse gebieden.', en: 'No one is innocent in Eastern territories.' }, author: { nl: 'Een oud-bondgenoot', en: 'A former ally' } },
 'quote-60': { text: { nl: 'Een gokje op Indonesië is het begin van het einde.', en: 'Taking a gamble on Indonesia is the beginning of the end.' }, author: { nl: 'De verliezende coalitie', en: 'The losing coalition' } },
 'quote-61': { text: { nl: 'Je strategie is waardeloos als je niet kan onderhandelen met terroristen.', en: 'Your strategy is worthless if you cannot negotiate with terrorists.' }, author: { nl: 'Een anonieme diplomaat', en: 'An anonymous diplomat' } },
 'quote-62': { text: { nl: 'In dit spel zijn er geen bondgenoten, alleen slachtoffers die voor later bewaard worden.', en: 'In this game there are no allies, only victims saved for later.' }, author: { nl: 'Een verraden bondgenoot', en: 'A betrayed ally' } },
 'quote-63': { text: { nl: 'Macht corrumpeert, en veel plastic legers corrumperen absoluut.', en: 'Power corrupts, and a lot of plastic armies corrupt absolutely.' }, author: { nl: 'Een zelfingenomen kolonel', en: 'A self-satisfied colonel' } },
 'quote-64': { text: { nl: 'Groot-Brittannië is een eiland dat snakt naar de verovering van West-Europa.', en: 'Great Britain is an island that yearns for the conquest of Western Europe.' }, author: { nl: 'De kaartenkamer', en: 'The map room' } },
 'quote-65': { text: { nl: 'Eén speler die onopvallend kaarten verzamelt, is gevaarlijker dan een openlijke tiran.', en: 'One player quietly hoarding cards is more dangerous than an outright tyrant.' }, author: { nl: 'Het dobbelsteenorakel', en: 'The dice oracle' } },
 'quote-66': { text: { nl: 'Het opzetten van het bord is de stilte voor de absolute chaos.', en: 'Setting up the board is the calm before absolute chaos.' }, author: { nl: 'Ongevraagd advies van een buurland', en: 'Unsolicited advice from a neighbor' } },
 'quote-67': { text: { nl: 'Je grenzen beveiligen betekent gewoon dat de vijand ergens anders aanvalt.', en: 'Securing your borders just means the enemy attacks somewhere else.' }, author: { nl: 'Een ambitieuze admiraal', en: 'An ambitious admiral' } },
 'quote-68': { text: { nl: 'Je kan je niet verbergen in het noordpoolgebied als het bord geen grenzen heeft.', en: 'You cannot hide in the Arctic when the board has no edges.' }, author: { nl: 'Voetnoot in het spelregelboekje', en: 'Footnote in the rulebook' } },
 'quote-69': { text: { nl: 'Een aanval die strandt op het laatste blokje is de ware tragedie van dit spel.', en: 'An attack that stalls on the last cube is the true tragedy of this game.' }, author: { nl: 'Een speler met te veel legers', en: 'A player with too many armies' } },
 'quote-70': { text: { nl: 'Je kan de speler de schuld geven, maar de schuldige is altijd de blinde ambitie.', en: 'You can blame the player, but the culprit is always blind ambition.' }, author: { nl: 'Veldheer in ruste', en: 'Retired commander' } },
 'quote-71': { text: { nl: 'Wie zijn leger verspreidt, nodigt de nederlaag uit voor een kopje thee.', en: 'He who spreads his army thin invites defeat in for a cup of tea.' }, author: { nl: 'Veroveraar in spe', en: 'Conqueror in the making' } },
 'quote-72': { text: { nl: 'De meest succesvolle generaals zijn degenen die meedogenloos zijn bij het kaartenspel.', en: 'The most successful generals are those who are ruthless at the card game.' }, author: { nl: 'Een speler met te weinig geluk', en: 'A player with too little luck' } },
 'quote-73': { text: { nl: 'Het Midden-Oosten is de rotonde van wereldheerschappij.', en: 'The Middle East is the roundabout of world domination.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-74': { text: { nl: 'Het opofferen van je bondgenoot is een geaccepteerde militaire tactiek.', en: 'Sacrificing your ally is an accepted military tactic.' }, author: { nl: 'Gepensioneerd veldmaarschalk', en: 'Retired field marshal' } },
 'quote-75': { text: { nl: 'De geur van angst is identiek aan de geur van een tegenstander met slechts twee territoria over.', en: 'The smell of fear is identical to the smell of an opponent with only two territories left.' }, author: { nl: 'De stem van de rode dobbelsteen', en: 'The voice of the red die' } },
 'quote-76': { text: { nl: 'Geen enkel plan overleeft het contact met de geluksfactor.', en: 'No plan survives contact with the luck factor.' }, author: { nl: 'Cynische kolonel', en: 'Cynical colonel' } },
 'quote-77': { text: { nl: 'Een beslissende slag winnen betekent alleen dat je de rest van het bord tegen je keert.', en: 'Winning a decisive battle just means turning the rest of the board against you.' }, author: { nl: 'Waarnemer aan de zijlijn', en: 'Sideline observer' } },
 'quote-78': { text: { nl: 'Een speler met niets te verliezen werpt de meest dodelijke dobbelstenen.', en: 'A player with nothing to lose rolls the most lethal dice.' }, author: { nl: 'Een moedeloze aanvaller', en: 'A disheartened attacker' } },
 'quote-79': { text: { nl: 'Verraden worden in beurt één is gewoon efficiënt gamen.', en: 'Being betrayed in turn one is just efficient gaming.' }, author: { nl: 'Onbekende strateeg', en: 'Unknown strategist' } },
 'quote-80': { text: { nl: 'Het bezit van de wereld is tijdelijk; de wrok van je vrienden is permanent.', en: 'Possession of the world is temporary; the resentment of your friends is permanent.' }, author: { nl: 'Toeschouwer met een mening', en: 'Opinionated onlooker' } },
 'quote-81': { text: { nl: 'De overwinning gaat naar de speler die zijn bloeddorst het best verbergt.', en: 'Victory goes to the player who best hides their bloodlust.' }, author: { nl: 'Een hoopvolle verdediger', en: 'A hopeful defender' } },
 'quote-82': { text: { nl: 'Als de rode speler lacht, controleer dan je grenzen.', en: 'If the red player smiles, check your borders.' }, author: { nl: 'Doorgewinterde veteraan', en: 'Seasoned veteran' } },
 'quote-83': { text: { nl: 'De echte diplomatie vindt plaats als de gastheer naar het toilet is.', en: 'True diplomacy occurs when the host goes to the bathroom.' }, author: { nl: 'Een kaartenhamsteraar', en: 'A card hoarder' } },
 'quote-84': { text: { nl: 'Een snelle expansie leidt tot een snelle ineenstorting.', en: 'Rapid expansion leads to rapid collapse.' }, author: { nl: 'Kroniekschrijver van het bord', en: 'Chronicler of the board' } },
 'quote-85': { text: { nl: 'Kamtsjatka is de achterdeur naar de hel.', en: 'Kamchatka is the back door to hell.' }, author: { nl: 'Bordspelfilosoof', en: 'Board game philosopher' } },
 'quote-86': { text: { nl: 'Verdedigingslinies zijn er om gebroken te worden door een gelukkige dwaas.', en: 'Defensive lines exist to be broken by a lucky fool.' }, author: { nl: 'Legendarische verliezer', en: 'Legendary loser' } },
 'quote-87': { text: { nl: 'Een massale opbouw in India voorspelt niets dan onweer in het oosten.', en: 'A massive buildup in India foretells nothing but a storm in the east.' }, author: { nl: 'Een speler zonder bondgenoten', en: 'A player without allies' } },
 'quote-88': { text: { nl: 'Wie Zuid-Amerika controleert, heeft tijd, geen ambitie.', en: 'Whoever controls South America has time, not ambition.' }, author: { nl: 'De legerleiding', en: 'Army command' } },
 'quote-89': { text: { nl: 'De groene speler is altijd bezig met een schaduwoorlog.', en: 'The green player is always fighting a shadow war.' }, author: { nl: 'Een zenuwachtige bondgenoot', en: 'A nervous ally' } },
 'quote-90': { text: { nl: 'Een meedogenloze leider kent de waarde van een tijdige opgave.', en: 'A ruthless leader knows the value of a timely surrender.' }, author: { nl: 'De laatste kaartenstapel', en: 'The last deck of cards' } },
 'quote-91': { text: { nl: 'De grens van je imperium is precies daar waar je weigert nog een blokje te plaatsen.', en: 'The border of your empire is exactly where you refuse to place another cube.' }, author: { nl: 'Frontlinie-wijsheid', en: 'Frontline wisdom' } },
 'quote-92': { text: { nl: 'Het verliezen van je thuisland is een teken dat je het universum boos hebt gemaakt.', en: 'Losing your homeland is a sign you have angered the universe.' }, author: { nl: 'Onderhandelaar zonder resultaat', en: 'Negotiator with no results' } },
 'quote-93': { text: { nl: 'De kunst van het spel is anderen elkaars legers te laten vernietigen.', en: 'The art of the game is letting others destroy each other\'s armies.' }, author: { nl: 'Een tacticus uit het niets', en: 'A tactician out of nowhere' } },
 'quote-94': { text: { nl: 'De definitie van overwinning is het enige plastic op tafel zijn.', en: 'The definition of victory is being the only plastic left on the table.' }, author: { nl: 'Een verbitterde verliezer', en: 'A bitter loser' } },
 'quote-95': { text: { nl: 'Niets isoleert een heerser zo snel als het veroveren van Europa.', en: 'Nothing isolates a ruler as quickly as conquering Europe.' }, author: { nl: 'Een tevreden veroveraar', en: 'A satisfied conqueror' } },
 'quote-96': { text: { nl: 'Een overvloed aan eenheden betekent slechts een overvloed aan doelwitten.', en: 'An abundance of units just means an abundance of targets.' }, author: { nl: 'Wijze woorden bij het opruimen van het bord', en: 'Wise words while packing up the board' } },
 'quote-97': { text: { nl: 'Het lot van de wereld wordt beslist door stukjes plastic in een doos.', en: 'The fate of the world is decided by pieces of plastic in a box.' }, author: { nl: 'Zelfverklaarde keizer', en: 'Self-proclaimed emperor' } },
 'quote-98': { text: { nl: 'Een vredesverklaring is gewoon een stilzwijgende instemming om later te vechten.', en: 'A declaration of peace is just a tacit agreement to fight later.' }, author: { nl: 'Laatste overlevende speler', en: 'Last surviving player' } },
 'quote-99': { text: { nl: 'Geen rijk valt zo snel als dat van de speler die even niet oplette.', en: 'No empire falls as quickly as that of the player who stopped paying attention.' }, author: { nl: 'Een generaal zonder leger', en: 'A general without an army' } },
 'quote-100': { text: { nl: 'De oorlog is koud, de dobbelstenen zijn koud, en het hart van je vriend is bevroren.', en: 'The war is cold, the dice are cold, and your friend\'s heart is frozen.' }, author: { nl: 'Een achterbankgeneraal', en: 'An armchair general' } },
 'quote-101': { text: { nl: 'Oost-Australië is een gevangenis, geen bolwerk.', en: 'Eastern Australia is a prison, not a stronghold.' }, author: { nl: 'Een gefrustreerde uitdager', en: 'A frustrated challenger' } },
 'quote-102': { text: { nl: 'Elke alliantie eindigt wanneer iemand Noord-Amerika claimt.', en: 'Every alliance ends when someone claims North America.' }, author: { nl: 'Oude veldheerswijsheid', en: 'Old commander\'s wisdom' } },
 'quote-103': { text: { nl: 'Een 6 gooien voelt als talent, een 1 als verraad van het universum.', en: 'Rolling a 6 feels like talent, a 1 like betrayal by the universe.' }, author: { nl: 'Overwinnaar van gisteren', en: 'Yesterday\'s victor' } },
 'quote-104': { text: { nl: 'De ergste leugen in Risk is \'ik val je volgende beurt niet aan\'.', en: 'The worst lie in Risk is \'I won\'t attack you next turn\'.' }, author: { nl: 'Kamergeleerde in tactiek', en: 'Armchair tactics scholar' } },
 'quote-105': { text: { nl: 'Drie infanterie-eenheden in IJsland zijn de bewakers van de westerse beschaving.', en: 'Three infantry units in Iceland are the guardians of western civilization.' }, author: { nl: 'Generaal aan het front', en: 'General at the front' } },
 'quote-106': { text: { nl: 'Een overwinning op papier is een nederlaag op het bord.', en: 'A victory on paper is a defeat on the board.' }, author: { nl: 'Anonieme militair strateeg', en: 'Anonymous military strategist' } },
 'quote-107': { text: { nl: 'De speler die zucht en zegt dat hij verliest, heeft zojuist vier kaarten verzameld.', en: 'The player who sighs and says they are losing just collected four cards.' }, author: { nl: 'Een stille waarnemer', en: 'A quiet observer' } },
 'quote-108': { text: { nl: 'Verraad is geen optie, het is een spelfase.', en: 'Betrayal is not an option, it is a game phase.' }, author: { nl: 'Strategisch handboek', en: 'Strategy handbook' } },
 'quote-109': { text: { nl: 'Niemand huilt om het verlies van Jakoetië.', en: 'No one cries over the loss of Yakutsk.' }, author: { nl: 'Een oud-bondgenoot', en: 'A former ally' } },
 'quote-110': { text: { nl: 'Een rijk opbouwen in Afrika is vragen om koloniale wraak.', en: 'Building an empire in Africa is asking for colonial revenge.' }, author: { nl: 'De verliezende coalitie', en: 'The losing coalition' } },
 'quote-111': { text: { nl: 'Zuid-Amerika is een valstrik vermomd als een bonus van twee legers.', en: 'South America is a trap disguised as a two-army bonus.' }, author: { nl: 'Een anonieme diplomaat', en: 'An anonymous diplomat' } },
 'quote-112': { text: { nl: 'Het is pas een wereldoorlog als Madagaskar valt.', en: 'It is only a world war when Madagascar falls.' }, author: { nl: 'Een verraden bondgenoot', en: 'A betrayed ally' } },
 'quote-113': { text: { nl: 'De beste verdediging is een speler die te bang is om aan te vallen.', en: 'The best defense is a player too afraid to attack.' }, author: { nl: 'Een zelfingenomen kolonel', en: 'A self-satisfied colonel' } },
 'quote-114': { text: { nl: 'Je grenzen versterken provoceert precies de aanval die je probeerde te voorkomen.', en: 'Fortifying your borders provokes exactly the attack you tried to prevent.' }, author: { nl: 'De kaartenkamer', en: 'The map room' } },
 'quote-115': { text: { nl: 'Een snelle expansie in Azië is een lange zelfmoordbrief.', en: 'A rapid expansion in Asia is a long suicide note.' }, author: { nl: 'Het dobbelsteenorakel', en: 'The dice oracle' } },
 'quote-116': { text: { nl: 'Vier legers verliezen aan één verdediger is een reden om geladen dobbelstenen te kopen.', en: 'Losing four armies to one defender is a reason to buy loaded dice.' }, author: { nl: 'Ongevraagd advies van een buurland', en: 'Unsolicited advice from a neighbor' } },
 'quote-117': { text: { nl: 'Je bouwt geen imperium met genade.', en: 'You do not build an empire with mercy.' }, author: { nl: 'Een ambitieuze admiraal', en: 'An ambitious admiral' } },
 'quote-118': { text: { nl: 'Een muur van plastic in Oeral is de enige buffer tussen beschaving en chaos.', en: 'A wall of plastic in Ural is the only buffer between civilization and chaos.' }, author: { nl: 'Voetnoot in het spelregelboekje', en: 'Footnote in the rulebook' } },
 'quote-119': { text: { nl: 'De loper van de dood marcheert altijd door het Midden-Oosten.', en: 'The harbinger of death always marches through the Middle East.' }, author: { nl: 'Een speler met te veel legers', en: 'A player with too many armies' } },
 'quote-120': { text: { nl: 'Wie de joker bewaart, controleert de toekomst.', en: 'He who saves the joker controls the future.' }, author: { nl: 'Veldheer in ruste', en: 'Retired commander' } },
 'quote-121': { text: { nl: 'Risico\'s nemen is goed, zolang een ander ze maar neemt.', en: 'Taking risks is good, as long as someone else takes them.' }, author: { nl: 'Veroveraar in spe', en: 'Conqueror in the making' } },
 'quote-122': { text: { nl: 'Er bestaat geen neutrale zone, alleen ongeclaimd slachtveld.', en: 'There is no neutral zone, only unclaimed battlefield.' }, author: { nl: 'Een speler met te weinig geluk', en: 'A player with too little luck' } },
 'quote-123': { text: { nl: 'Een vroege overwinning in Europa trekt de blik van de rest van de wereld.', en: 'An early victory in Europe draws the gaze of the rest of the world.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-124': { text: { nl: 'Het verzamelen van kaarten is de stille klok van de naderende apocalyps.', en: 'Collecting cards is the silent clock of the impending apocalypse.' }, author: { nl: 'Gepensioneerd veldmaarschalk', en: 'Retired field marshal' } },
 'quote-125': { text: { nl: 'De grens tussen Venezuela en Brazilië is besmeurd met onzichtbaar bloed.', en: 'The border between Venezuela and Brazil is stained with invisible blood.' }, author: { nl: 'De stem van de rode dobbelsteen', en: 'The voice of the red die' } },
 'quote-126': { text: { nl: 'Congo is het zwarte gat waar legers in verdwijnen.', en: 'Congo is the black hole where armies disappear.' }, author: { nl: 'Cynische kolonel', en: 'Cynical colonel' } },
 'quote-127': { text: { nl: 'Australië vasthouden is een test van geduld, niet van vaardigheid.', en: 'Holding Australia is a test of patience, not skill.' }, author: { nl: 'Waarnemer aan de zijlijn', en: 'Sideline observer' } },
 'quote-128': { text: { nl: 'Niemand wint door stil te zitten in Peru, maar de alpaca\'s zijn wel schattig.', en: 'No one wins by sitting still in Peru, but the alpacas are cute.' }, author: { nl: 'Een moedeloze aanvaller', en: 'A disheartened attacker' } },
 'quote-129': { text: { nl: 'Een artillerie-eenheid in Ontario is een diplomatiek incident dat wacht om te gebeuren.', en: 'An artillery unit in Ontario is a diplomatic incident waiting to happen.' }, author: { nl: 'Onbekende strateeg', en: 'Unknown strategist' } },
 'quote-130': { text: { nl: 'De laatste beurt van een geëlimineerde speler is de meest destructieve kracht op aarde.', en: 'The final turn of an eliminated player is the most destructive force on earth.' }, author: { nl: 'Toeschouwer met een mening', en: 'Opinionated onlooker' } },
 'quote-131': { text: { nl: 'Verwacht geen loyaliteit van de speler in het groen.', en: 'Expect no loyalty from the player in green.' }, author: { nl: 'Een hoopvolle verdediger', en: 'A hopeful defender' } },
 'quote-132': { text: { nl: 'Een ondoordringbare grens is slechts een uitdaging voor de ware fanaat.', en: 'An impenetrable border is merely a challenge to the true fanatic.' }, author: { nl: 'Doorgewinterde veteraan', en: 'Seasoned veteran' } },
 'quote-133': { text: { nl: 'De verovering van Groenland is een logistieke nachtmerrie.', en: 'The conquest of Greenland is a logistical nightmare.' }, author: { nl: 'Een kaartenhamsteraar', en: 'A card hoarder' } },
 'quote-134': { text: { nl: 'Je legers concentreren is een teken van naderende agressie.', en: 'Concentrating your armies is a sign of imminent aggression.' }, author: { nl: 'Kroniekschrijver van het bord', en: 'Chronicler of the board' } },
 'quote-135': { text: { nl: 'De speler die het meest praat, verbergt de zwakste grenzen.', en: 'The player who talks the most hides the weakest borders.' }, author: { nl: 'Bordspelfilosoof', en: 'Board game philosopher' } },
 'quote-136': { text: { nl: 'Elke infanterist telt, totdat je er dertig in één beurt verliest.', en: 'Every infantryman counts, until you lose thirty in one turn.' }, author: { nl: 'Legendarische verliezer', en: 'Legendary loser' } },
 'quote-137': { text: { nl: 'De stilte na een mislukte invasie is oorverdovend.', en: 'The silence following a failed invasion is deafening.' }, author: { nl: 'Een speler zonder bondgenoten', en: 'A player without allies' } },
 'quote-138': { text: { nl: 'Zuid-Europa is de zachte onderbuik van de wereld.', en: 'Southern Europe is the soft underbelly of the world.' }, author: { nl: 'De legerleiding', en: 'Army command' } },
 'quote-139': { text: { nl: 'Het binnenvallen van China is altijd een rekenfout.', en: 'Invading China is always a miscalculation.' }, author: { nl: 'Een zenuwachtige bondgenoot', en: 'A nervous ally' } },
 'quote-140': { text: { nl: 'Dobbelstenen hebben geen geheugen, maar spelers wel.', en: 'Dice have no memory, but players do.' }, author: { nl: 'De laatste kaartenstapel', en: 'The last deck of cards' } },
 'quote-141': { text: { nl: 'Een vredesakkoord in beurt vier is oplichterij in beurt vijf.', en: 'A peace accord in turn four is a scam in turn five.' }, author: { nl: 'Frontlinie-wijsheid', en: 'Frontline wisdom' } },
 'quote-142': { text: { nl: 'Scandinavië is het balkon van waaruit men Europa ziet branden.', en: 'Scandinavia is the balcony from which one watches Europe burn.' }, author: { nl: 'Onderhandelaar zonder resultaat', en: 'Negotiator with no results' } },
 'quote-143': { text: { nl: 'Wie de oceanen controleert, controleert niets; het gaat om de grenzen.', en: 'Whoever controls the oceans controls nothing; it is about the borders.' }, author: { nl: 'Een tacticus uit het niets', en: 'A tactician out of nowhere' } },
 'quote-144': { text: { nl: 'De droom van een verenigd Afrika sterft altijd in Egypte.', en: 'The dream of a united Africa always dies in Egypt.' }, author: { nl: 'Een verbitterde verliezer', en: 'A bitter loser' } },
 'quote-145': { text: { nl: 'Een aanval vanuit Alaska is altijd persoonlijk.', en: 'An attack from Alaska is always personal.' }, author: { nl: 'Een tevreden veroveraar', en: 'A satisfied conqueror' } },
 'quote-146': { text: { nl: 'Je beste vriend aan tafel is je ergste vijand over dertig minuten.', en: 'Your best friend at the table is your worst enemy in thirty minutes.' }, author: { nl: 'Wijze woorden bij het opruimen van het bord', en: 'Wise words while packing up the board' } },
 'quote-147': { text: { nl: 'Als de artillerie rolt, zwijgt de diplomatie.', en: 'When the artillery rolls, diplomacy falls silent.' }, author: { nl: 'Zelfverklaarde keizer', en: 'Self-proclaimed emperor' } },
 'quote-148': { text: { nl: 'De kunst van oorlog is wachten tot twee dwazen elkaar uitputten.', en: 'The art of war is waiting for two fools to exhaust each other.' }, author: { nl: 'Laatste overlevende speler', en: 'Last surviving player' } },
 'quote-149': { text: { nl: 'Een rijk valt niet door aanvallen van buitenaf, maar door hoogmoed.', en: 'An empire falls not by external attacks, but by hubris.' }, author: { nl: 'Een generaal zonder leger', en: 'A general without an army' } },
 'quote-150': { text: { nl: 'Het Noorden onthoudt alles, vooral de invasie van Siberië.', en: 'The North remembers everything, especially the invasion of Siberia.' }, author: { nl: 'Een achterbankgeneraal', en: 'An armchair general' } },
 'quote-151': { text: { nl: 'Eén overgebleven leger in het Midden-Amerikaanse oerwoud kan een wereldmacht doen wankelen.', en: 'One remaining army in the Central American jungle can make a world power stumble.' }, author: { nl: 'Een gefrustreerde uitdager', en: 'A frustrated challenger' } },
 'quote-152': { text: { nl: 'De overwinning is een koude minnares.', en: 'Victory is a cold mistress.' }, author: { nl: 'Oude veldheerswijsheid', en: 'Old commander\'s wisdom' } },
 'quote-153': { text: { nl: 'Zodra je denkt dat je veilig bent, kaapt iemand de route via Kamtsjatka.', en: 'As soon as you think you are safe, someone hijacks the route through Kamchatka.' }, author: { nl: 'Overwinnaar van gisteren', en: 'Yesterday\'s victor' } },
 'quote-154': { text: { nl: 'Verraad in Risk is geen zonde, het is een overlevingsstrategie.', en: 'Betrayal in Risk is not a sin, it is a survival strategy.' }, author: { nl: 'Kamergeleerde in tactiek', en: 'Armchair tactics scholar' } },
 'quote-155': { text: { nl: 'De echte overwinning is wanneer niemand meer een potje met je wil spelen.', en: 'The real victory is when no one wants to play a game with you anymore.' }, author: { nl: 'Generaal aan het front', en: 'General at the front' } },
 'quote-156': { text: { nl: 'Een leger in Tsjita is net zo onzichtbaar als dodelijk.', en: 'An army in Irkutsk is as invisible as it is deadly.' }, author: { nl: 'Anonieme militair strateeg', en: 'Anonymous military strategist' } },
 'quote-157': { text: { nl: 'Oorlog voeren in de Oekraïne vereist blind vertrouwen in de rode dobbelstenen.', en: 'Waging war in Ukraine requires blind faith in the red dice.' }, author: { nl: 'Een stille waarnemer', en: 'A quiet observer' } },
 'quote-158': { text: { nl: 'Het offeren van een cavalerie is de prijs van vooruitgang.', en: 'Sacrificing a cavalry is the price of progress.' }, author: { nl: 'Strategisch handboek', en: 'Strategy handbook' } },
 'quote-159': { text: { nl: 'Wie huilt over één verloren gebied, verdient niet het continent.', en: 'He who cries over one lost territory does not deserve the continent.' }, author: { nl: 'Een oud-bondgenoot', en: 'A former ally' } },
 'quote-160': { text: { nl: 'Zonder infanterie stort de hele infrastructuur van angst in.', en: 'Without infantry, the entire infrastructure of fear collapses.' }, author: { nl: 'De verliezende coalitie', en: 'The losing coalition' } },
 'quote-161': { text: { nl: 'De eerste speler die uitschakelt wordt, is de enige met een ontspannen avond.', en: 'The first player eliminated is the only one with a relaxed evening.' }, author: { nl: 'Een anonieme diplomaat', en: 'An anonymous diplomat' } },
 'quote-162': { text: { nl: 'Een fort bouwen in West-Europa is wachten op een belegering.', en: 'Building a fortress in Western Europe is waiting for a siege.' }, author: { nl: 'Een verraden bondgenoot', en: 'A betrayed ally' } },
 'quote-163': { text: { nl: 'De langste mars begint met één stap in Oost-Afrika.', en: 'The longest march begins with a single step in East Africa.' }, author: { nl: 'Een zelfingenomen kolonel', en: 'A self-satisfied colonel' } },
 'quote-164': { text: { nl: 'Als je geen vijanden hebt, speel je het spel verkeerd.', en: 'If you have no enemies, you are playing the game wrong.' }, author: { nl: 'De kaartenkamer', en: 'The map room' } },
 'quote-165': { text: { nl: 'De grensverdediging in Mongolië is slechts een formaliteit.', en: 'The border defense in Mongolia is merely a formality.' }, author: { nl: 'Het dobbelsteenorakel', en: 'The dice oracle' } },
 'quote-166': { text: { nl: 'Een ware commandant gooit de dobbelstenen zonder te kijken.', en: 'A true commander rolls the dice without looking.' }, author: { nl: 'Ongevraagd advies van een buurland', en: 'Unsolicited advice from a neighbor' } },
 'quote-167': { text: { nl: 'Het is niet het verlies dat pijn doet, het is de glimlach van je tegenstander.', en: 'It is not the loss that hurts, it is the smile of your opponent.' }, author: { nl: 'Een ambitieuze admiraal', en: 'An ambitious admiral' } },
 'quote-168': { text: { nl: 'De laatste hoop van de mensheid rust in de handen van één infanterist in Argentinië.', en: 'The last hope of humanity rests in the hands of one infantryman in Argentina.' }, author: { nl: 'Voetnoot in het spelregelboekje', en: 'Footnote in the rulebook' } },
 'quote-169': { text: { nl: 'Strategie eindigt waar de wanhoop begint.', en: 'Strategy ends where desperation begins.' }, author: { nl: 'Een speler met te veel legers', en: 'A player with too many armies' } },
 'quote-170': { text: { nl: 'Elke opbouwfase is een stilgezwegen bedreiging.', en: 'Every reinforcement phase is a silent threat.' }, author: { nl: 'Veldheer in ruste', en: 'Retired commander' } },
 'quote-171': { text: { nl: 'De weg naar dominantie is geplaveid met geruïneerde relaties.', en: 'The road to dominance is paved with ruined relationships.' }, author: { nl: 'Veroveraar in spe', en: 'Conqueror in the making' } },
 'quote-172': { text: { nl: 'Een tactische terugtrekking is een nederlaag met een strikje erom.', en: 'A tactical retreat is a defeat with a bow on it.' }, author: { nl: 'Een speler met te weinig geluk', en: 'A player with too little luck' } },
 'quote-173': { text: { nl: 'Wie de wereld wil, moet bereid zijn zijn buren te vertrappen.', en: 'He who wants the world must be willing to trample his neighbors.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-174': { text: { nl: 'Een vergeten leger in Nieuw-Guinea is de ondergang van Azië.', en: 'A forgotten army in New Guinea is the downfall of Asia.' }, author: { nl: 'Gepensioneerd veldmaarschalk', en: 'Retired field marshal' } },
 'quote-175': { text: { nl: 'De lach van de winnaar is het meest irritante geluid op aarde.', en: 'The laugh of the winner is the most annoying sound on earth.' }, author: { nl: 'De stem van de rode dobbelsteen', en: 'The voice of the red die' } },
 'quote-176': { text: { nl: 'Als je niet wordt aangevallen, ben je de volgende prooi.', en: 'If you are not being attacked, you are the next prey.' }, author: { nl: 'Cynische kolonel', en: 'Cynical colonel' } },
 'quote-177': { text: { nl: 'Een rijk zonder achterdeur is een gevangenis.', en: 'An empire without a backdoor is a prison.' }, author: { nl: 'Waarnemer aan de zijlijn', en: 'Sideline observer' } },
 'quote-178': { text: { nl: 'De kracht van de invasie is recht evenredig met de wanhoop van de speler.', en: 'The power of the invasion is directly proportional to the desperation of the player.' }, author: { nl: 'Een moedeloze aanvaller', en: 'A disheartened attacker' } },
 'quote-179': { text: { nl: 'Een kaart inleveren om in leven te blijven is pure vernedering.', en: 'Turning in a card to stay alive is pure humiliation.' }, author: { nl: 'Onbekende strateeg', en: 'Unknown strategist' } },
 'quote-180': { text: { nl: 'Europa is een slachthuis met een hoge huur.', en: 'Europe is a slaughterhouse with high rent.' }, author: { nl: 'Toeschouwer met een mening', en: 'Opinionated onlooker' } },
 'quote-181': { text: { nl: 'Wie het noorden van Azië in handen heeft, heeft niets dan kou en vijanden.', en: 'Whoever holds the north of Asia has nothing but cold and enemies.' }, author: { nl: 'Een hoopvolle verdediger', en: 'A hopeful defender' } },
 'quote-182': { text: { nl: 'Zuid-Afrika is het veiligste land, totdat de rest van Afrika valt.', en: 'South Africa is the safest country, until the rest of Africa falls.' }, author: { nl: 'Doorgewinterde veteraan', en: 'Seasoned veteran' } },
 'quote-183': { text: { nl: 'Een invasie zonder plan is een massamoord op je eigen troepen.', en: 'An invasion without a plan is a mass murder of your own troops.' }, author: { nl: 'Een kaartenhamsteraar', en: 'A card hoarder' } },
 'quote-184': { text: { nl: 'De grens van Brazilië is de test van elke vriendschap.', en: 'The border of Brazil is the test of every friendship.' }, author: { nl: 'Kroniekschrijver van het bord', en: 'Chronicler of the board' } },
 'quote-185': { text: { nl: 'Een verdediger die drieën gooit is onsterfelijk.', en: 'A defender who rolls threes is immortal.' }, author: { nl: 'Bordspelfilosoof', en: 'Board game philosopher' } },
 'quote-186': { text: { nl: 'Je continent opgeven voor kaarten is zakendoen.', en: 'Giving up your continent for cards is doing business.' }, author: { nl: 'Legendarische verliezer', en: 'Legendary loser' } },
 'quote-187': { text: { nl: 'Een speler die de regels betwist, staat op het punt te verliezen.', en: 'A player who disputes the rules is about to lose.' }, author: { nl: 'Een speler zonder bondgenoten', en: 'A player without allies' } },
 'quote-188': { text: { nl: 'De ware grootte van een leger is niet zichtbaar totdat het te laat is.', en: 'The true size of an army is not visible until it is too late.' }, author: { nl: 'De legerleiding', en: 'Army command' } },
 'quote-189': { text: { nl: 'Wie zich in Oeral verschanst, zit in de gulag.', en: 'He who entrenches himself in Ural sits in the gulag.' }, author: { nl: 'Een zenuwachtige bondgenoot', en: 'A nervous ally' } },
 'quote-190': { text: { nl: 'De zeeën bieden geen bescherming tegen een wraakzuchtige buurman.', en: 'The seas offer no protection against a vengeful neighbor.' }, author: { nl: 'De laatste kaartenstapel', en: 'The last deck of cards' } },
 'quote-191': { text: { nl: 'Een bondgenoot is gewoon een vijand die op een beter moment wacht.', en: 'An ally is just an enemy waiting for a better moment.' }, author: { nl: 'Frontlinie-wijsheid', en: 'Frontline wisdom' } },
 'quote-192': { text: { nl: 'De stilte van de zwarte stukken is intimiderend.', en: 'The silence of the black pieces is intimidating.' }, author: { nl: 'Onderhandelaar zonder resultaat', en: 'Negotiator with no results' } },
 'quote-193': { text: { nl: 'De wereld veroveren in één beurt vereist pure wiskunde.', en: 'Conquering the world in one turn requires pure mathematics.' }, author: { nl: 'Een tacticus uit het niets', en: 'A tactician out of nowhere' } },
 'quote-194': { text: { nl: 'Een wanhopige uitval in Midden-Amerika markeert het einde van een tijdperk.', en: 'A desperate sortie in Central America marks the end of an era.' }, author: { nl: 'Een verbitterde verliezer', en: 'A bitter loser' } },
 'quote-195': { text: { nl: 'De blik in de ogen van de verliezer is de ware trofee.', en: 'The look in the eyes of the loser is the true trophy.' }, author: { nl: 'Een tevreden veroveraar', en: 'A satisfied conqueror' } },
 'quote-196': { text: { nl: 'Een onbeschermde flank is een uitnodiging voor rampspoed.', en: 'An unprotected flank is an invitation to disaster.' }, author: { nl: 'Wijze woorden bij het opruimen van het bord', en: 'Wise words while packing up the board' } },
 'quote-197': { text: { nl: 'De verdediging van Oost-Amerika rust op hoop en slechte berekeningen.', en: 'The defense of Eastern United States rests on hope and bad calculations.' }, author: { nl: 'Zelfverklaarde keizer', en: 'Self-proclaimed emperor' } },
 'quote-198': { text: { nl: 'Wie controleert wie? De speler de legers, of de legers de speler?', en: 'Who controls whom? The player the armies, or the armies the player?' }, author: { nl: 'Laatste overlevende speler', en: 'Last surviving player' } },
 'quote-199': { text: { nl: 'Een alliantie verbreken voor één gebied is de definitie van kleinzerigheid.', en: 'Breaking an alliance for one territory is the definition of pettiness.' }, author: { nl: 'Een generaal zonder leger', en: 'A general without an army' } },
 'quote-200': { text: { nl: 'De wereld is te klein voor twee ego\'s en zeven continenten.', en: 'The world is too small for two egos and seven continents.' }, author: { nl: 'Een achterbankgeneraal', en: 'An armchair general' } },
 'quote-201': { text: { nl: 'Een goede vijand is een dode vijand.', en: 'A good enemy is a dead enemy.' }, author: { nl: 'Elke generaal ooit', en: 'Every general ever' } },
 'quote-202': { text: { nl: 'Als de muren hoog zijn, haal dan langere ladders.', en: 'If the walls are high, get bigger ladders.' }, author: { nl: 'Donald J. Trump, Truth Social', en: 'Donald J. Trump, Truth Social' } },
 'quote-203': { text: { nl: 'Nooit marcheren op een lege maag.', en: 'Never march on an empty stomach.' }, author: { nl: 'Napoleon, waarschijnlijk', en: 'Napoleon, probably' } },
 'quote-204': { text: { nl: 'Speren zijn gewoon lange messen.', en: 'Spears are just long knives.' }, author: { nl: 'Onbekende hopliet', en: 'Unknown hoplite' } },
 'quote-205': { text: { nl: 'Water werkt beter tegen vuur dan zwaarden.', en: 'Water works better against fire than swords.' }, author: { nl: 'Romeinse brandweer', en: 'Roman fire department' } },
 'quote-206': { text: { nl: 'Als het paard dood is, moet je afstappen.', en: 'If the horse is dead, dismount.' }, author: { nl: 'Indiaans spreekwoord', en: 'Native American proverb' } },
 'quote-207': { text: { nl: 'Blijf laag als ze schieten.', en: 'Stay low when they shoot.' }, author: { nl: 'Gezond verstand', en: 'Common sense' } },
 'quote-208': { text: { nl: 'Kastelen zijn leuk tot de voedselvoorraad op is.', en: 'Castles are fun until the food runs out.' }, author: { nl: 'Middeleeuwse wijsheid', en: 'Medieval wisdom' } },
 'quote-209': { text: { nl: 'Huurlingen vechten beter als je ze betaalt.', en: 'Mercenaries fight better when you pay them.' }, author: { nl: 'Machiavelli, ergens', en: 'Machiavelli, somewhere' } },
 'quote-210': { text: { nl: 'Een helm beschermt alleen als je hem draagt.', en: 'A helmet only protects if you wear it.' }, author: { nl: 'Spartaanse moeder', en: 'Spartan mother' } },
 'quote-211': { text: { nl: 'Vergeet niet omhoog te kijken bij kasteelmuren.', en: 'Do not forget to look up near castle walls.' }, author: { nl: 'Aanvallers handboek', en: 'Attacker handbook' } },
 'quote-212': { text: { nl: 'Kruit moet droog blijven. Echt waar.', en: 'Gunpowder needs to stay dry. Seriously.' }, author: { nl: 'Guy Fawkes, achteraf', en: 'Guy Fawkes, in hindsight' } },
 'quote-213': { text: { nl: 'Als we omsingeld zijn, kunnen we alle kanten op schieten.', en: 'If we are surrounded, we can shoot in every direction.' }, author: { nl: 'Amerikaanse marinier', en: 'US Marine' } },
 'quote-214': { text: { nl: 'Olifanten zijn indrukwekkend, maar onhandig in de bergen.', en: 'Elephants are impressive, but clumsy in the mountains.' }, author: { nl: 'Hannibal, evaluatie', en: 'Hannibal, evaluation' } },
 'quote-215': { text: { nl: 'Berenkuilen werken alleen als je ze verstopt.', en: 'Bear traps only work if you hide them.' }, author: { nl: 'Jagersgilde', en: 'Hunters guild' } },
 'quote-216': { text: { nl: 'Wij zijn erg goed in verrassingsfeestjes en partijen.', en: 'We are very good in suprise parties' }, author: { nl: 'De Spaanse Inquititie', en: 'The Spanish Inquisition' } },
 'quote-217': { text: { nl: 'Verander niet van paard in het midden van de rivier.', en: 'Do not change horses in midstream.' }, author: { nl: 'Abraham Lincoln, misschien', en: 'Abraham Lincoln, maybe' } },
 'quote-218': { text: { nl: 'Zorg voor schone sokken.', en: 'Take care of your feet and change your socks.' }, author: { nl: 'Luitenant Dan', en: 'Lieutenant Dan' } },
 'quote-219': { text: { nl: 'Zwaarden worden bot, knuppels niet.', en: 'Swords get dull, clubs do not.' }, author: { nl: 'Orkische logica', en: 'Orcish logic' } },
 'quote-220': { text: { nl: 'Een gracht is slechts een natte greppel.', en: 'A moat is just a wet ditch.' }, author: { nl: 'Geniepionier', en: 'Combat engineer' } },
 'quote-221': { text: { nl: 'Gedeelde pijn is nog steeds pijn.', en: 'Shared pain is still pain.' }, author: { nl: 'Cynische veteraan', en: 'Cynical veteran' } },
 'quote-222': { text: { nl: 'Als de aanval perfect verloopt, loop je in een hinderlaag.', en: 'If the attack goes perfectly, it is an ambush.' }, author: { nl: 'Infanterie regel', en: 'Infantry rule' } },
 'quote-223': { text: { nl: 'Vriendelijk vuur is niet vriendelijk.', en: 'Friendly fire is not friendly.' }, author: { nl: 'Militaire paradox', en: 'Military paradox' } },
 'quote-224': { text: { nl: 'Rennen is een acceptabele tactiek als je in de minderheid bent.', en: 'Running is an acceptable tactic when outnumbered.' }, author: { nl: 'Franse revolutie', en: 'French revolution' } },
 'quote-225': { text: { nl: 'Sneeuw en legers gaan slecht samen.', en: 'Snow and armies mix poorly.' }, author: { nl: 'Russische tsaar', en: 'Russian tsar' } },
 'quote-226': { text: { nl: 'Een kanonskogel heeft altijd voorrang.', en: 'A cannonball always has the right of way.' }, author: { nl: 'Artillerie handboek', en: 'Artillery manual' } },
 'quote-227': { text: { nl: 'Pijlen op? Gooi stenen.', en: 'Out of arrows? Throw rocks.' }, author: { nl: 'Wanhopige boogschutter', en: 'Desperate archer' } },
 'quote-228': { text: { nl: 'Als jij de vijand niet ziet, zien zij jou misschien wel.', en: 'If you cannot see the enemy, they might still see you.' }, author: { nl: 'Scherpschutter', en: 'Sniper' } },
 'quote-229': { text: { nl: 'Zand in de ogen werkt beter dan een mooi plan.', en: 'Sand in the eyes works better than a nice plan.' }, author: { nl: 'Gladiatoren wijsheid', en: 'Gladiator wisdom' } },
 'quote-230': { text: { nl: 'Bruggen zijn handig totdat de vijand eroverheen komt.', en: 'Bridges are useful until the enemy crosses them.' }, author: { nl: 'Julius Caesar, wellicht', en: 'Julius Caesar, perhaps' } },
 'quote-231': { text: { nl: 'Houten paarden zijn verdacht.', en: 'Wooden horses are suspicious.' }, author: { nl: 'Trojaanse wachter, te laat', en: 'Trojan guard, too late' } },
 'quote-232': { text: { nl: 'Een groot zwaard compenseert een gebrek aan vaardigheid.', en: 'A big sword compensates for a lack of skill.' }, author: { nl: 'Barbaar, waarschijnlijk', en: 'Barbarian, probably' } },
 'quote-233': { text: { nl: 'Wie betaalt, bepaalt de marsroute.', en: 'He who pays, decides the marching route.' }, author: { nl: 'Huurling', en: 'Mercenary' } },
 'quote-234': { text: { nl: 'Oorlog is luid.', en: 'War is loud.' }, author: { nl: 'Dove artillerist', en: 'Deaf artilleryman' } },
 'quote-235': { text: { nl: 'Tenten lekken altijd.', en: 'Tents always leak.' }, author: { nl: 'Romeins legioen', en: 'Roman legion' } },
 'quote-236': { text: { nl: 'Slaap met één oog open als je soldaten niet betaald zijn.', en: 'Sleep with one eye open if your soldiers are unpaid.' }, author: { nl: 'Keizerlijke regel', en: 'Imperial rule' } },
 'quote-237': { text: { nl: 'Een schildpadformatie is traag, net als een echte schildpad.', en: 'A testudo formation is slow, just like a real turtle.' }, author: { nl: 'Centurion', en: 'Centurion' } },
 'quote-238': { text: { nl: 'Verdwijn in de mist van de oorlog, als er überhaupt mist is.', en: 'Vanish in the fog of war, if there is any fog.' }, author: { nl: 'Tun Szu, van horen zeggen', en: 'Tun Szu, hearsay' } },
 'quote-239': { text: { nl: 'Modder is de grootste vijand van een leger.', en: 'Mud is the greatest enemy of an army.' }, author: { nl: 'Veldmaarschalk', en: 'Field marshal' } },
 'quote-240': { text: { nl: 'Een boog zonder pees is gewoon een stok.', en: 'A bow without a string is just a stick.' }, author: { nl: 'Robin Hood, misschien', en: 'Robin Hood, maybe' } },
 'quote-241': { text: { nl: 'Aanvallen bij zonsopgang betekent vroeg opstaan.', en: 'Attacking at dawn means waking up early.' }, author: { nl: 'Klagerige soldaat', en: 'Complaining soldier' } },
 'quote-242': { text: { nl: 'Een kroon is zwaar, een helm is zwaarder.', en: 'A crown is heavy, a helmet is heavier.' }, author: { nl: 'Koning te velde', en: 'King in the field' } },
 'quote-243': { text: { nl: 'Kruisbogen zijn voor mensen die niet willen oefenen.', en: 'Crossbows are for people who do not want to practice.' }, author: { nl: 'Engelse langboogschutter', en: 'English longbowman' } },
 'quote-244': { text: { nl: 'Als het brandt, gooi er dan geen olie op.', en: 'If it burns, do not throw oil on it.' }, author: { nl: 'Byzantijnse misvatting', en: 'Byzantine misconception' } },
 'quote-245': { text: { nl: 'Verkenners sterven meestal als eerste.', en: 'Scouts usually die first.' }, author: { nl: 'Verkenner', en: 'Scout' } },
 'quote-246': { text: { nl: 'Een vredesverdrag is slechts een pauze.', en: 'A peace treaty is just a pause.' }, author: { nl: 'Cynische diplomaat', en: 'Cynical diplomat' } },
 'quote-247': { text: { nl: 'Trek niet aan de staart van een oorlogsolifant.', en: 'Do not pull the tail of a war elephant.' }, author: { nl: 'Indische wijsheid', en: 'Indian wisdom' } },
 'quote-248': { text: { nl: 'Als ze wegrennen, schiet ze dan in de rug.', en: 'If they run away, shoot them in the back.' }, author: { nl: 'Machiavelli, waarschijnlijk', en: 'Machiavelli, probably' } },
 'quote-249': { text: { nl: 'Goud wint meer veldslagen dan ijzer.', en: 'Gold wins more battles than iron.' }, author: { nl: 'Rijke handelaar', en: 'Wealthy merchant' } },
 'quote-250': { text: { nl: 'Zonder infanterie ben je ook nergens.', en: 'Without infantry, you are also nowhere.' }, author: { nl: 'Iedereen, altijd', en: 'Everyone, always' } },
 'quote-251': { text: { nl: 'Als de strategie niet werkt, schreeuw dan harder.', en: 'If the strategy fails, shout louder.' }, author: { nl: 'Onbekende officier', en: 'Unknown officer' } },
 'quote-252': { text: { nl: 'Een reserveplan is voor mensen die geen vertrouwen hebben in plan A.', en: 'A backup plan is for people lacking faith in plan A.' }, author: { nl: 'Blinde optimist', en: 'Blind optimist' } },
 'quote-253': { text: { nl: 'Wie als eerste schiet, heeft minder munitie over.', en: 'He who shoots first has less ammo left.' }, author: { nl: 'Zuinige schutter', en: 'Frugal shooter' } },
 'quote-254': { text: { nl: 'Kogels onderscheiden geen rang of stand.', en: 'Bullets do not distinguish rank or status.' }, author: { nl: 'Dodelijke gelijkheid', en: 'Deadly equality' } },
 'quote-255': { text: { nl: 'Een fort zonder voedsel is een hongerbunker.', en: 'A fortress without food is a starvation bunker.' }, author: { nl: 'Belegger', en: 'Besiege commander' } },
 'quote-256': { text: { nl: 'Als de rook optrekt, zie je wie er nog staat.', en: 'When the smoke clears, you see who is still standing.' }, author: { nl: 'Slagveld observatie', en: 'Battlefield observation' } },
 'quote-257': { text: { nl: 'Een goede helm verbergt een hoop angst.', en: 'A good helmet hides a lot of fear.' }, author: { nl: 'Jonge rekruut', en: 'Young recruit' } },
 'quote-258': { text: { nl: 'Paarden eten meer dan soldaten en klagen vaker.', en: 'Horses eat more than soldiers and complain more.' }, author: { nl: 'Quartermaster', en: 'Quartermaster' } },
 'quote-259': { text: { nl: 'Wie snel rent, overleeft de strategische terugtocht.', en: 'He who runs fast survives the strategic retreat.' }, author: { nl: 'Vluchtende eenheid', en: 'Fleeing unit' } },
 'quote-260': { text: { nl: 'Het weer kiest nooit partij, het haat iedereen.', en: 'The weather never takes sides, it hates everyone.' }, author: { nl: 'Infanterist in de regen', en: 'Infantryman in the rain' } },
 'quote-261': { text: { nl: 'Het enige wat sneller instort dan een alliantie, is een speler die \'vertrouw me\' zegt.', en: 'The only thing that collapses faster than an alliance is a player saying, \'Trust me.' }, author: { nl: 'Een gefrustreerde uitdager', en: 'A frustrated challenger' } },
 'quote-262': { text: { nl: 'Een leger van vijftig voelt verrassend klein zodra de dobbelstenen beginnen te rollen.', en: 'An army of fifty suddenly feels very small once the dice start rolling.' }, author: { nl: 'Oude veldheerswijsheid', en: 'Old commander\'s wisdom' } },
 'quote-263': { text: { nl: 'Australië is geen strategie; het is een levensstijl.', en: 'Australia is not a strategy; it is a lifestyle.' }, author: { nl: 'Overwinnaar van gisteren', en: 'Yesterday\'s victor' } },
 'quote-264': { text: { nl: 'Ik pak alleen even één gebiedje.', en: 'I am only taking one territory.' }, author: { nl: 'De grootste leugen sinds het niet-aanvalsverdrag.', en: 'The biggest lie since the non-aggression pact.' } },
 'quote-265': { text: { nl: 'Iedere speler is een genie totdat de eerste aanval drie enen oplevert.', en: 'Every player is a genius until their first attack rolls three ones.' }, author: { nl: 'Kamergeleerde in tactiek', en: 'Armchair tactics scholar' } },
 'quote-266': { text: { nl: 'Sun Tzu schreef niets over dobbelstenen. Dat zegt eigenlijk al genoeg.', en: 'Sun Tzu never wrote about dice. That tells you everything.' }, author: { nl: 'Generaal aan het front', en: 'General at the front' } },
 'quote-267': { text: { nl: 'Wie Kamtsjatka bezit, bezit vooral slapeloze nachten.', en: 'Whoever owns Kamchatka mostly owns sleepless nights.' }, author: { nl: 'Anonieme militair strateeg', en: 'Anonymous military strategist' } },
 'quote-268': { text: { nl: 'Een continentbonus voelt als belastingteruggave: precies op tijd om hem weer kwijt te raken.', en: 'A continent bonus is like a tax refund: just in time to lose it again.' }, author: { nl: 'Een stille waarnemer', en: 'A quiet observer' } },
 'quote-269': { text: { nl: 'De gevaarlijkste speler heeft geen groot leger, maar een pokerface tijdens de versterkingsfase.', en: 'The most dangerous player does not have the biggest army, but the best poker face during reinforcements.' }, author: { nl: 'Strategisch handboek', en: 'Strategy handbook' } },
 'quote-270': { text: { nl: 'Wie denkt dat Winterfell moeilijk te verdedigen is, heeft nog nooit Azië gehad.', en: 'Anyone who thinks Winterfell is hard to defend has never held Asia.' }, author: { nl: 'Een oud-bondgenoot', en: 'A former ally' } },
 'quote-271': { text: { nl: 'Caesar kwam, zag en zou waarschijnlijk eerst kaarten hebben ingeleverd.', en: 'Caesar came, saw, and would probably have turned in his cards first.' }, author: { nl: 'De verliezende coalitie', en: 'The losing coalition' } },
 'quote-272': { text: { nl: 'Alexander de Grote had nooit een continentbonus nodig.', en: 'Alexander the Great never needed a continent bonus.' }, author: { nl: 'Een anonieme diplomaat', en: 'An anonymous diplomat' } },
 'quote-273': { text: { nl: 'Churchill zou nooit opgeven. Behalve misschien na drie opeenvolgende enen.', en: 'Churchill would never surrender. Except perhaps after three consecutive ones.' }, author: { nl: 'Een verraden bondgenoot', en: 'A betrayed ally' } },
 'quote-274': { text: { nl: 'Napoleon verloor meer aan logistiek dan aan zijn vijanden.', en: 'Napoleon lost more to logistics than to his enemies.' }, author: { nl: 'Een zelfingenomen kolonel', en: 'A self-satisfied colonel' } },
 'quote-275': { text: { nl: 'De vijand is slim. Daarom nemen we aan dat hij vandaag vrij heeft.', en: 'The enemy is clever. That is why we assume he took the day off.' }, author: { nl: 'Onbezorgde officier', en: 'Carefree officer' } },
 'quote-276': { text: { nl: 'Caesar zou eerst de brug bouwen en daarna pas de overwinning opeisen.', en: 'Caesar would build the bridge before claiming the victory.' }, author: { nl: 'De kaartenkamer', en: 'The map room' } },
 'quote-277': { text: { nl: 'Zelfs Napoleon had een reserveplan. Dat heette alleen geen Rusland.', en: 'Even Napoleon had a backup plan. It just was not called Russia.' }, author: { nl: 'Het dobbelsteenorakel', en: 'The dice oracle' } },
 'quote-278': { text: { nl: 'Zelfs Churchill had niet kunnen onderhandelen met een slechte dobbelsteen.', en: 'Even Churchill could not have negotiated with a bad die.' }, author: { nl: 'Ongevraagd advies van een buurland', en: 'Unsolicited advice from a neighbor' } },
 'quote-279': { text: { nl: 'De soldaten vroegen om een plan. Ik gaf ze vertrouwen. Het was goedkoper.', en: 'The soldiers asked for a plan. I gave them confidence. It was cheaper.' }, author: { nl: 'Koning Henry the 3th', en: 'King Henry the 3th' } },
 'quote-280': { text: { nl: 'Het plan werkte uitstekend tijdens de repetitie.', en: 'The plan worked perfectly during rehearsal.' }, author: { nl: 'Oorlogsminister', en: 'Minister of War' } },
 'quote-281': { text: { nl: 'Een overwinning zonder verliezen bestaat alleen op kaarten.', en: 'A victory without losses exists only on maps.' }, author: { nl: 'Een ambitieuze admiraal', en: 'An ambitious admiral' } },
 'quote-282': { text: { nl: 'Zelfs Caesar moest ooit beginnen met zijn eerste overwinning.', en: 'Even Caesar had to start with his first victory.' }, author: { nl: 'Voetnoot in het spelregelboekje', en: 'Footnote in the rulebook' } },
 'quote-283': { text: { nl: 'De slimste generaals winnen niet door harder te vechten, maar door slimmer te denken.', en: 'The smartest generals win not by fighting harder, but by thinking better.' }, author: { nl: 'Een speler met te veel legers', en: 'A player with too many armies' } },
 'quote-284': { text: { nl: 'Ik vind jouw gebrek aan een reserveplan verontrustend.', en: 'I find your lack of a backup plan disturbing.' }, author: { nl: 'Darth Vader, waarschijnlijk', en: 'Darth Vader, probably' } },
 'quote-285': { text: { nl: 'Een Death Star bouwen is eenvoudig. De ventilatie is het moeilijke deel.', en: 'Building a Death Star is easy. The ventilation is the hard part.' }, author: { nl: 'Keizerlijke ingenieur', en: 'Imperial engineer' } },
 'quote-286': { text: { nl: 'Als de kaarten gelijk hebben, lopen we nu door een rivier.', en: 'If the maps are right, we are currently walking through a river.' }, author: { nl: 'Verkenner', en: 'Scout' } },
 'quote-287': { text: { nl: 'We hadden de overwinning bijna binnen. Toen begon de vergadering.', en: 'Victory was almost ours. Then the meeting started.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-288': { text: { nl: 'Het mooie aan een reserveplan is dat je kunt doen alsof het altijd Plan A was.', en: 'The beauty of a backup plan is pretending it was Plan A all along.' }, author: { nl: 'Veldheer', en: 'Commander' } },
 'quote-289': { text: { nl: 'De vijand was uitstekend voorbereid. Dat vonden wij nogal onsportief.', en: 'The enemy was extremely well prepared. We considered that rather unsporting.' }, author: { nl: 'Infanterist', en: 'Infantryman' } },
 'quote-290': { text: { nl: 'Ik heb volledige controle over de situatie.', en: 'I have complete control of the situation.' }, author: { nl: 'Napoleon, Waterloo', en: 'Napoleon, Waterloo' } },
 'quote-291': { text: { nl: 'Een goede soldaat weet waar de vijand is. Een slimme soldaat weet waar de koffie is.', en: 'A good soldier knows where the enemy is. A smart soldier knows where the coffee is.' }, author: { nl: 'Veldheer in ruste', en: 'Retired commander' } },
 'quote-292': { text: { nl: 'We vallen aan om kwart over twee, mits de NS geen vertraging heeft.', en: 'We attack at a quarter past two, provided the national railways are on time.' }, author: { nl: 'Strategische planning', en: 'Strategic planning' } },
 'quote-293': { text: { nl: 'Een kaart lezen is eenvoudig. Hem op de juiste manier vasthouden blijkt moeilijker.', en: 'Reading a map is easy. Holding it the right way is harder.' }, author: { nl: 'Veroveraar in spe', en: 'Conqueror in the making' } },
 'quote-294': { text: { nl: 'Vrede is vaak gewoon een pauze waarin beide partijen herladen.', en: 'Peace is often just a pause while both sides reload.' }, author: { nl: 'Een speler met te weinig geluk', en: 'A player with too little luck' } },
 'quote-295': { text: { nl: 'Het luidste zwaard is niet altijd het scherpste.', en: 'The loudest sword is not always the sharpest.' }, author: { nl: 'Stafofficier', en: 'Staff officer' } },
 'quote-296': { text: { nl: 'De kortste weg naar een overwinning is zorgen dat niemand een slecht nieuwsbericht durft te brengen.', en: 'The shortest path to victory is making sure nobody dares deliver bad news.' }, author: { nl: 'Jozef Staling', en: 'Joseph Stalin' } },
 'quote-297': { text: { nl: 'Een lange tafel voorkomt korte discussies.', en: 'A long table prevents short discussions.' }, author: { nl: 'Vladimir Poetin, tijdens een vergadering', en: 'Vladimir Putin, during a meeting' } },
 'quote-298': { text: { nl: 'Ik ben beleid', en: 'I am the policy' }, author: { nl: 'In ieder geval geen Nederlandse Asielminister', en: 'At least not a Minister of Asylum in the Netherlands' } },
 'quote-299': { text: { nl: 'Ik heb hier geen actieve herinnering aan', en: 'I have no active memory of this' }, author: { nl: 'Onbekende bron', en: 'Unknown source' } },
 'quote-300': { text: { nl: 'Een compromis is een overwinning waarin iedereen evenveel baalt', en: 'A compromise is a victory where everyone is equally bummed out.' }, author: { nl: 'Gepensioneerd veldmaarschalk', en: 'Retired field marshal' } },
} satisfies LocaleTree
